router6.post("/create-session", authenticateToken, async (req, res) => {
  try {
    const { orderId, amount, provider, isSubscription, subscriptionId } = req.body;
    if (!orderId || !amount || !provider) {
      return res.status(400).json({ error: "orderId, amount y provider son requeridos" });
    }
    const amountEur = amount / 100;
    switch (provider) {
      case "stripe_card":
      case "stripe_bizum": {
        const stripe2 = getStripe();
        const payment_method_types = provider === "stripe_bizum" ? ["bizum"] : ["card"];
        let productName = `Pedido ComeYa #${orderId.slice(-6)}`;
        if (isSubscription) {
          productName = subscriptionId ? `Suscripci\xF3n ComeYa ${subscriptionId.slice(-6)}` : `Suscripci\xF3n ComeYa Premium/Business`;
        }
        const session = await stripe2.checkout.sessions.create({
          payment_method_types,
          line_items: [
            {
              price_data: {
                currency: "eur",
                product_data: { name: productName },
                unit_amount: amount
              },
              quantity: 1
            }
          ],
          mode: "payment",
          success_url: `${process.env.BACKEND_URL}/api/payments/success?orderId=${orderId}&provider=${provider}&isSubscription=${!!isSubscription}&subscriptionId=${subscriptionId || ""}`,
          cancel_url: `${process.env.BACKEND_URL}/api/payments/cancel?orderId=${orderId}&isSubscription=${!!isSubscription}`,
          metadata: {
            orderId,
            provider,
            isSubscription: isSubscription ? "true" : "false",
            subscriptionId: subscriptionId || ""
          }
        });
        return res.json({ url: session.url, sessionId: session.id });
      }
      case "paypal": {
        const base = process.env.PAYPAL_MODE === "live" ? "https://api-m.paypal.com" : "https://api-m.sandbox.paypal.com";
        const tokenRes = await fetch(`${base}/v1/oauth2/token`, {
          method: "POST",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            Authorization: `Basic ${Buffer.from(`${process.env.PAYPAL_CLIENT_ID}:${process.env.PAYPAL_SECRET}`).toString("base64")}`
          },
          body: "grant_type=client_credentials"
        });
        const tokenData = await tokenRes.json();
        const orderRes = await fetch(`${base}/v2/checkout/orders`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${tokenData.access_token}`
          },
          body: JSON.stringify({
            intent: "CAPTURE",
            purchase_units: [
              {
                reference_id: orderId,
                amount: { currency_code: "EUR", value: amountEur.toFixed(2) }
              }
            ],
            application_context: {
              return_url: `${process.env.BACKEND_URL}/api/payments/success?orderId=${orderId}&provider=paypal`,
              cancel_url: `${process.env.BACKEND_URL}/api/payments/cancel?orderId=${orderId}`
            }
          })
        });
        const paypalOrder = await orderRes.json();
        const approveLink = paypalOrder.links?.find(
          (l) => l.rel === "approve"
        )?.href;
        return res.json({ url: approveLink, paypalOrderId: paypalOrder.id });
      }
      case "binance": {
        const crypto4 = await import("crypto");
        const nonce = crypto4.randomBytes(16).toString("hex");
        const timestamp2 = Date.now();
        const merchantId = process.env.BINANCE_MERCHANT_ID;
        const apiKey = process.env.BINANCE_API_KEY;
        const secretKey = process.env.BINANCE_SECRET_KEY;
        const body = JSON.stringify({
          env: { terminalType: "APP" },
          merchantTradeNo: orderId.replace(/-/g, "").slice(0, 32),
          orderAmount: amountEur.toFixed(2),
          currency: "EUR",
          goods: {
            goodsType: "01",
            goodsCategory: "Z000",
            referenceGoodsId: orderId,
            goodsName: `Pedido ComeYa #${orderId.slice(-6)}`
          },
          returnUrl: `${process.env.BACKEND_URL}/api/payments/success?orderId=${orderId}&provider=binance`,
          cancelUrl: `${process.env.BACKEND_URL}/api/payments/cancel?orderId=${orderId}`
        });
        const payload = `${timestamp2}
${nonce}
${body}
`;
        const signature = crypto4.createHmac("sha512", secretKey).update(payload).digest("hex").toUpperCase();
        const binanceRes = await fetch(
          "https://bpay.binanceapi.com/binancepay/openapi/v2/order",
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "BinancePay-Timestamp": String(timestamp2),
              "BinancePay-Nonce": nonce,
              "BinancePay-Certificate-SN": apiKey,
              "BinancePay-Signature": signature
            },
            body
          }
        );
        const binanceData = await binanceRes.json();
        return res.json({
          url: binanceData.data?.checkoutUrl,
          binanceOrderId: binanceData.data?.prepayId
        });
      }
      default:
        return res.status(400).json({ error: "Provider no soportado" });
    }
  } catch (error) {
    console.error("Create payment session error:", error);
    res.status(500).json({ error: error.message });
  }
});
