router8.put(
  "/verifications/:userId",
  authenticateToken,
  requireRole("admin", "super_admin"),
  async (req, res) => {
    try {
      const { users: users5, auditLogs: auditLogs2 } = await Promise.resolve().then(() => (init_schema_mysql(), schema_mysql_exports));
      const { db: db2 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const { eq: eq72 } = await import("drizzle-orm");
      const { action, notes } = req.body;
      const userId = req.params.userId;
      if (!action || !["approve", "reject"].includes(action)) {
        return res.status(400).json({ error: "action debe ser 'approve' o 'reject'" });
      }
      const verificationStatus = action === "approve" ? "verified" : "rejected";
      const isActive = action === "approve";
      if (action === "approve") {
        const [targetUser] = await db2.select().from(users5).where(eq72(users5.id, userId)).limit(1);
        if (targetUser?.role === "delivery_driver") {
          const { deliveryDrivers: deliveryDrivers3 } = await Promise.resolve().then(() => (init_schema_mysql(), schema_mysql_exports));
          const [dd] = await db2.select().from(deliveryDrivers3).where(eq72(deliveryDrivers3.userId, userId)).limit(1);
          const missing = [];
          if (!targetUser.idDocumentUrl)
            missing.push("DNI/NIE (anverso)");
          if (!dd?.vehicleLicensePhoto)
            missing.push("Permiso de circulaci\xF3n");
          if (!dd?.vehiclePhoto)
            missing.push("Foto del veh\xEDculo");
          if (missing.length > 0) {
            return res.status(400).json({
              error: "El repartidor no ha subido todos los documentos requeridos: " + missing.join(", ")
            });
          }
        }
      }
      await db2.update(users5).set({
        verificationStatus,
        verificationNotes: notes || null,
        isActive
      }).where(eq72(users5.id, userId));
      await db2.insert(auditLogs2).values({
        userId: req.user.id,
        action: action === "approve" ? "verify_user_approved" : "verify_user_rejected",
        entityType: "user",
        entityId: userId,
        changes: JSON.stringify({ verificationStatus, notes })
      });
      try {
        const { sendPushToUser: sendPushToUser2 } = await Promise.resolve().then(() => (init_enhancedPushService(), enhancedPushService_exports));
        await sendPushToUser2(userId, {
          title: action === "approve" ? "\u2705 Cuenta verificada" : "\u274C Verificaci\xF3n rechazada",
          body: action === "approve" ? "Tu cuenta ha sido verificada. Ya puedes usar ComeYa." : `Tu verificaci\xF3n fue rechazada. ${notes || "Contacta con soporte para m\xE1s informaci\xF3n."}`,
          data: { screen: "Profile" }
        });
      } catch {
      }
      res.json({ success: true, verificationStatus });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  }
);
router8.get(
  "/profile/stats",
  authenticateToken,
  requireRole("admin", "super_admin"),
  async (req, res) => {
    try {
      const { db: db2 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const adminId = req.user.id;
      const result = await db2.execute(import_drizzle_orm26.sql`
      SELECT
        COUNT(*) as totalActions,
        SUM(action LIKE 'verify%') as verificationsProcessed,
        SUM(entity_type = 'payout') as payoutsProcessed,
        SUM(entity_type = 'payment_proof') as proofsReviewed,
        MAX(created_at) as lastActionAt
      FROM audit_logs
      WHERE user_id = ${adminId}
    `);
      const rows = Array.isArray(result[0]) ? result[0] : result;
      const stats = rows[0] || {};
      const pending = await db2.execute(import_drizzle_orm26.sql`
      SELECT
        (SELECT COUNT(*) FROM payment_proofs WHERE status = 'pending') as pendingProofs,
        (SELECT COUNT(*) FROM payouts WHERE status = 'pending') as pendingPayouts,
        (SELECT COUNT(*) FROM orders WHERE status IN ('pending','confirmed','preparing','on_the_way')) as activeOrders
    `);
      const pendingRows = Array.isArray(pending[0]) ? pending[0] : pending;
      const pendingData = pendingRows[0] || {};
      res.json({
        success: true,
        stats: {
          totalActions: Number(stats.totalActions) || 0,
          verificationsProcessed: Number(stats.verificationsProcessed) || 0,
          payoutsProcessed: Number(stats.payoutsProcessed) || 0,
          proofsReviewed: Number(stats.proofsReviewed) || 0,
          lastActionAt: stats.lastActionAt || null
        },
        pending: {
          proofs: Number(pendingData.pendingProofs) || 0,
          payouts: Number(pendingData.pendingPayouts) || 0,
          orders: Number(pendingData.activeOrders) || 0
        }
      });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  }
);
